from math import sqrt,isfinite
def f(x):
    if isinstance(x,bool) or not isinstance(x,(int,float)) or not isfinite(x) or x<1 or x==2:raise ValueError("Fora do domínio")
    return sqrt(x-1)/(x-2)
for x in (0,2):
    try:f(x)
    except ValueError:pass
    else:raise AssertionError("Deveria rejeitar")
assert f(1)==0
